//! Frame dissection: link layer, network layer, transport payload.
//!
//! Generated by RustGenerators — do not edit.

/// Ethernet II
const ETHERNET: u32 = 1;
/// Raw IP, no link layer
const RAW: u32 = 101;
/// Linux cooked capture
const LINUX_SLL: u32 = 113;
/// Linux cooked capture v2
const LINUX_SLL2: u32 = 276;

/// The UDP or TCP payload of one captured frame, or None when the frame's
/// link, network, or transport layer is not one this reader dissects.
#[must_use]
pub fn payload(link: u32, frame: &[u8]) -> Option<&[u8]> {
    match link {
        ETHERNET => ethernet(frame),
        RAW => network(frame),
        // 16-byte header; the protocol type sits in its last two bytes
        LINUX_SLL => protocol(u16(frame, 14)?, frame.get(16..)?),
        // 20-byte header; the protocol type leads it
        LINUX_SLL2 => protocol(u16(frame, 0)?, frame.get(20..)?),
        _ => None,
    }
}

/// Ethernet II: 12 bytes of addresses, then an ethertype.
fn ethernet(frame: &[u8]) -> Option<&[u8]> {
    protocol(u16(frame, 12)?, frame.get(14..)?)
}

/// Network layer selected by ethertype, past any VLAN tags stacked in front of
/// it. Tags follow the link header of both Ethernet and Linux cooked captures.
fn protocol(mut ethertype: u16, mut packet: &[u8]) -> Option<&[u8]> {
    loop {
        match ethertype {
            0x0800 | 0x86dd => return network(packet),
            // 802.1Q and 802.1ad tags: two bytes of tag control, then the next type
            0x8100 | 0x88a8 | 0x9100 => {
                ethertype = u16(packet, 2)?;
                packet = packet.get(4..)?;
            }
            _ => return None,
        }
    }
}

/// IPv4 or IPv6, selected by the leading version nibble
fn network(packet: &[u8]) -> Option<&[u8]> {
    match packet.first()? >> 4 {
        4 => version4(packet),
        6 => version6(packet),
        _ => None,
    }
}

/// IPv4: header length from the IHL nibble, payload bounded by the total
/// length so any link-layer trailer is excluded.
fn version4(packet: &[u8]) -> Option<&[u8]> {
    let header = usize::from(packet.first()? & 0x0f) * 4;
    let total = usize::from(u16(packet, 2)?);
    let transport = packet.get(header..total)?;
    payload_of(*packet.get(9)?, transport)
}

/// IPv6: fixed 40-byte header, payload length and next header in it.
/// Extension headers are not walked — none appear in the corpus.
fn version6(packet: &[u8]) -> Option<&[u8]> {
    let length = usize::from(u16(packet, 4)?);
    let transport = packet.get(40..40 + length)?;
    payload_of(*packet.get(6)?, transport)
}

/// Transport payload by IP protocol number
fn payload_of(protocol: u8, transport: &[u8]) -> Option<&[u8]> {
    match protocol {
        // UDP: fixed 8-byte header, payload bounded by its length field
        17 => {
            let length = usize::from(u16(transport, 4)?);
            transport.get(8..length.max(8))
        }
        // TCP: header length from the data offset nibble
        6 => {
            let data = usize::from(*transport.get(12)? >> 4) * 4;
            transport.get(data..)
        }
        _ => None,
    }
}

fn u16(bytes: &[u8], at: usize) -> Option<u16> {
    let slice = bytes.get(at..at + 2)?;
    Some(u16::from_be_bytes(slice.try_into().ok()?))
}
